V.profileEdit=()=>{const p=init().profile;return H('Edit profile','Make it yours.',`${form('saveProfile',`${L.field('Display name','displayName','What friends call you','text',p.displayName||p.name||'').replace('<input ','<input maxlength="50" ').replace('autocomplete="off"','autocomplete="nickname"')}${L.field('Lumo handle','handle','your.name','text',p.handle||'').replace('<input ','<input maxlength="20" autocapitalize="none" spellcheck="false" ')}${L.field('Email · optional','email','you@example.com','email',p.email||'').replace('<input ','<input maxlength="254" ')}<p class="small muted">Changes stay on this device. Email verification is not connected.</p><div class="actions">${submit('Save changes')}${B('Discard changes',"if(confirm('Discard your unsaved changes?'))L.go('profile')",'text-btn')}</div>`)} `);};
V.profilePhone=()=>H('Change phone number','Keep your account within reach.',`${form('savePhone',`${L.field('New phone number','newPhone','024 000 1111','tel','').replace('<input ','<input maxlength="16" ').replace('autocomplete="off"','autocomplete="tel"')}${authField()}${L.field('Confirmation code','phoneOtp','6-digit code','text','').replace('<input ','<input inputmode="numeric" maxlength="6" ').replace('autocomplete="off"','autocomplete="one-time-code"')}<p class="small muted">Preview code: 123456. No SMS is sent.</p>${submit('Update phone number')}`)}${L.row('Lost access to your phone?','Start account recovery','help',"L.go('recovery')")}`);
V.security=()=>H('Security','A little care goes a long way.',`<div class="list">${L.row('Change PIN','Your 6-digit sign-in PIN','lock',"L.go('changePin')")}${L.row('Biometric sign-in','Face and fingerprint sign-in are unavailable','eye','L.acct.bio()','Unavailable')}${L.row('Your devices','Review where you are signed in','phone',"L.go('devices')")}${L.row('Lost phone or account access','Find your way back in','help',"L.go('recovery')")}</div><div class="soft"><h3>Keep your PIN to yourself.</h3><p class="small muted">Lumo support will never ask you to share your PIN or verification code.</p></div><p class="small muted">Security settings illustrate the flow on this device. Live account protection is not connected.</p>`);
