V.devices=()=>{const devices=init().devices.filter(d=>L.testMode||d.current);return H('Your devices','Know where you are signed in.',`${devices.map(d=>`<div class="card"><div class="topline"><strong>${E(d.name)}</strong>${d.current?status('This device'):''}</div><p class="small muted">${E(d.last)}</p>${!d.current?B('End session',`L.acct.endSession('${d.id}')`,'secondary'):''}</div>`).join('')}${devices.some(d=>!d.current)?authField():''}${B('Sign out of this device','L.acct.signout()','secondary')}<p class="small muted">This preview only shows activity saved in this browser. Other devices are not connected.</p>${L.row('Do not recognise a payment?','Find it in Activity','receipt',"L.go('activity')")}`);};
V.privacy=()=>{const p=init().accountPrefs;return H('Privacy','Your information. Your choices.',`${pref('Personalised suggestions','Saved preference; suggestions are not connected','chat',"L.acct.toggle('personalisation')",p.personalisation)}${pref('Marketing messages','Saved preference; no messages are sent','bell',"L.acct.toggle('marketing')",p.marketing)}<div class="section-head"><h3>Your information</h3></div>${L.row('Download your data','Get a copy of your saved information','download',"L.go('dataExport')")}${L.row('Correct your details','Review your profile','user',"L.go('profile')")}${L.row('Request data deletion','Review what can be removed','help',"L.acct.help('Data deletion request','PRIVACY','privacy')")}<p class="small muted">Preferences are saved on this device. Data requests are not sent to a live service.</p><details class="notice small"><summary>About your information</summary><p>This preview stores sample profile, plan and activity data in your browser. Account closure and data deletion are separate requests. Live privacy terms and retention rules must be confirmed before launch.</p></details>`);};
L.acct.sanitizeExport=safeRecord;
